-    if (y != 0) {
-        return (x + y - 1) / y;
-    }
-    return x;
-}
-int64_t DownAlign(int64_t x, int64_t y) {
-    if (y == 0) {
-        return x;
-    }
-    return (x / y) * y;
-}
-int64_t RoundUp(int64_t x, int64_t y) {
-    return CeilDiv(x, y) * y;
