-    if (GetPlatformInfo() == ge::GRAPH_FAILED) {
-        return ge::GRAPH_FAILED;
-    }
-
-    if (GetShapeAttrsInfoInner() == ge::GRAPH_FAILED) {
-        return ge::GRAPH_FAILED;
-    }
-
-    if (CheckShapesAndAttrs() == ge::GRAPH_FAILED) {
-        return ge::GRAPH_FAILED;
-    }
-
-    if (CalcOpTiling() == ge::GRAPH_FAILED) {
-        return ge::GRAPH_FAILED;
