-    uint64_t curUbFactorA = ubFactorA;
-    for (uint64_t idx = 0; idx < aUbLoopCount; idx++) {
-        if (idx == aUbLoopCount - 1) {
-            curUbFactorA = tailUbFactorA;
-        }
-        CopyIn(idx, curUbFactorA);
-        Compute(curUbFactorA);
-        CopyOut(idx, curUbFactorA);
-    }
-}
