-    if constexpr (sizeof(T) == B16_TYPE_BYTE_SIZE) {
-        ComputeB16(curUbFactorA);
-    } else if constexpr (sizeof(T) == B32_TYPE_BYTE_SIZE) {
-        ComputeB32(curUbFactorA);
