-    AscendC::Div(yLocal, reduceLocal, yLocal, curUbFactorA);
-
-    outQueueY.EnQue<float>(yLocal);
-    inQueueX.FreeTensor(xLocal);
-}
-
-template <typename T>
-__aicore__ inline void HcPreInvRmsFullLoad<T>::ComputeB32(uint64_t curUbFactorA)
-{
