-    float meanCof = 1.0f / R;
-    PipeBarrier<PIPE_V>();
-    AscendC::Muls(yLocal, yLocal, meanCof, curUbFactorA);
-    PipeBarrier<PIPE_V>();
-    AscendC::Adds(yLocal, yLocal, epsilon, curUbFactorA);
